CREATE TABLE public.education_schools (
    id character varying(80) NOT NULL,
    national_code character varying(60) NOT NULL,
    name_ar character varying(500) NOT NULL,
    name_en character varying(500) NOT NULL,
    search_text text NOT NULL,
    school_type character varying(60) NOT NULL,
    governorate_id character varying(20),
    directorate_id character varying(80),
    region character varying(20) NOT NULL,
    latitude double precision,
    longitude double precision,
    coordinate_source character varying(500),
    source_row integer NOT NULL,
    source_values json NOT NULL,
    CONSTRAINT school_coordinate_pair CHECK ((((latitude IS NULL) AND (longitude IS NULL)) OR ((latitude IS NOT NULL) AND (longitude IS NOT NULL)))),
    CONSTRAINT school_coordinate_source CHECK (((latitude IS NULL) OR (coordinate_source IS NOT NULL))),
    CONSTRAINT school_latitude CHECK (((latitude IS NULL) OR ((latitude >= ('-90'::integer)::double precision) AND (latitude <= (90)::double precision)))),
    CONSTRAINT school_longitude CHECK (((longitude IS NULL) OR ((longitude >= ('-180'::integer)::double precision) AND (longitude <= (180)::double precision))))
);


